        finally{$switch(true);$clean([$session['operation']]);$remoteCalls=$oldCalls;$remoteIds=$oldIds;$remoteState='prepared';}
    };
    $tests['single-account pilot limits the selected brand for all days and outcomes while preserving original-operation recovery']=function()use($app,$c,$owner,$beta,$meta,&$brand):void {
        $pilot=new ControlCenter\Config($c->root,array_replace($c->values,['trial_pilot_brand_id'=>$brand['id']]));$secrets=new ControlCenter\Secrets($pilot);$calls=0;
        $worker=new ControlCenter\TrialWorker($pilot,function($path,$body)use(&$calls):string {same('/branded-trials/provision',$path);$calls++;$s=json_decode($body,true);return json_encode(['state'=>'prepared','operation_id'=>$s['operation_id'],'reseller_id'=>$s['reseller_id'],'line_id'=>'920001','plan_id'=>$s['package_id'],'plan_fingerprint'=>$s['plan_fingerprint'],'notes_recorded'=>true,'account'=>['username'=>'SYNTHETIC','password'=>'SYNTHETIC','activation_code'=>'123456','exp_date'=>time()+86400]]);});
        $policies=new ControlCenter\TrialPolicies($app->db,$app->management,$app->auth,$worker);$artifacts=new ControlCenter\BrandArtifacts($app->db,$secrets,$pilot);$offers=new ControlCenter\TrialOffers($app->db,$pilot,$app->management,$app->auth,$secrets,$policies,$artifacts);$sessions=new ControlCenter\TrialPublicSessions($app->db,$offers,$secrets,$app->auth);$contacts=new ControlCenter\TrialContacts($app->db,$app->management,$app->auth,$secrets,$pilot,$worker);$broker=new ControlCenter\TrialSignupBroker($app->db,$pilot,$secrets,$app->auth,$offers,$sessions,new ControlCenter\TrialBudgets($app->db,$pilot),$worker,$contacts);
        $other=new ControlCenter\Config($c->root,array_replace($c->values,['trial_pilot_brand_id'=>str_repeat('f',32)]));$otherOffers=new ControlCenter\TrialOffers($app->db,$other,$app->management,$app->auth,$secrets,$policies,$artifacts);same(['available'=>false],$otherOffers->publicInfo($brand['id']));problem(409,fn()=> $otherOffers->publish($beta,['expected_revision'=>(int)$otherOffers->managerState($beta,[])['publication']['revision'],'enabled'=>true,'confirmed_public_mode'=>true,'daily_limit'=>1]));
        same(false,$otherOffers->managerState($beta,[])['can_publish']);same(1,$offers->managerState($owner,['tenant_id'=>$brand['tenant_id']])['pilot']['remaining']);
        $invalid=new ControlCenter\Config($c->root,array_replace($c->values,['trial_pilot_brand_id'=>'']));$invalidOffers=new ControlCenter\TrialOffers($app->db,$invalid,$app->management,$app->auth,$secrets,$policies,$artifacts);problem(503,fn()=> $invalidOffers->publicInfo($brand['id']));
        $created=[];$make=function(string $phone,string $device,mixed $key=null)use($sessions,$offers,&$brand,&$created):array {$key??=openssl_pkey_new(['private_key_type'=>OPENSSL_KEYTYPE_EC,'curve_name'=>'prime256v1']);$pem=openssl_pkey_get_details($key)['key'];$der=base64_decode(preg_replace('~-----[^\n]+-----|\s~','',$pem));$contact=ControlCenter\TrialContacts::contact(['first_name'=>'TEST Pilot','phone'=>$phone]);$hash=ControlCenter\TrialPublicSessions::requestHash($contact);$s=$sessions->create(['brand_id'=>$brand['id'],'offer_revision'=>$offers->publicInfo($brand['id'])['offer_revision'],'device_claim'=>$device,'public_key'=>base64_encode($der),'request_hash'=>$hash],'127.0.0.220');$created[]=$s['operation_id'];openssl_sign($s['signing_text'],$sig,$key,OPENSSL_ALGO_SHA256);return ['key'=>$key,'operation'=>$s['operation_id'],'input'=>['token'=>$s['token'],'nonce'=>$s['nonce'],'signature'=>base64_encode($sig),'request_hash'=>$hash,'first_name'=>$contact['first_name'],'phone'=>$contact['phone'],'notice_accepted'=>true]];};
        // This suite owns a random disposable LOCAL database. Respect the real
        // budget-lock-before-transaction order; clean up only these synthetic IDs.
        // Never use this fixture cleanup to reset an actual live pilot.
        try{
            $first=$make('+15550000901',str_repeat('c',64));$second=$make('+15550000902',str_repeat('d',64));same('prepared',$broker->submit($first['input'])['state']);same(1,$calls);problem(429,fn()=> $broker->submit($second['input']));same(1,$calls);
            same(0,$offers->managerState($owner,['tenant_id'=>$brand['tenant_id']])['pilot']['remaining']);same('prepared',$offers->managerState($owner,['tenant_id'=>$brand['tenant_id']])['pilot']['state']);
            same('prepared',$broker->submit($first['input'])['state']);$resume=$make('+15550000901',str_repeat('c',64),$first['key']);same('prepared',$broker->submit($resume['input'])['state']);same(1,$calls);
            $app->db->query('UPDATE trial_signup_operations SET created_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY) WHERE id=?',[$first['operation']]);$app->db->query('UPDATE trial_signup_budgets SET created_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY),counted=0 WHERE operation_id=?',[$first['operation']]);
            foreach(['reserved','sending','retry_wait','failed','needs_review','cancelled','prepared','delivered'] as $state){$app->db->query('UPDATE trial_signup_operations SET state=? WHERE id=?',[$state,$first['operation']]);problem(429,fn()=> $broker->submit($second['input']));}
            same(1,$calls);
        }finally{foreach($created as $operation){$app->db->query('DELETE FROM trial_contacts WHERE operation_id=?',[$operation]);$app->db->query('DELETE FROM trial_signup_budgets WHERE operation_id=?',[$operation]);$app->db->query('DELETE FROM trial_signup_operations WHERE id=?',[$operation]);$app->db->query('DELETE FROM trial_public_sessions WHERE operation_id=?',[$operation]);}}
    };
    $tests['public key possession plus notice binds one signup to server-owned reseller plan and scoped result']=function()use($app,$broker,$makeSession,&$remoteCalls,&$sessionData):void {
        $sessionData=$makeSession('+15550000001',str_repeat('a',64));$in=$sessionData['input'];problem(422,fn()=> $broker->submit(array_replace($in,['reseller_id'=>'999'])));problem(422,fn()=> $broker->submit(array_replace($in,['notice_accepted'=>false])));problem(401,fn()=> $broker->submit(array_replace($in,['signature'=>base64_encode('invalid')])));
        $result=$broker->submit($in);same('prepared',$result['state']);same('123456',$result['activation_code']);same(1,$remoteCalls);same($result,$broker->submit($in));same(1,$remoteCalls);check(!isset($result['username'],$result['password'],$result['reseller_id']));
        $row=$app->db->one('SELECT * FROM trial_signup_operations WHERE id=?',[$result['operation_id']]);same(null,$row['request_cipher']);check(!str_contains($row['activation_cipher'],'123456'));$contact=$app->db->one('SELECT contact_cipher FROM trial_contacts WHERE operation_id=?',[$result['operation_id']]);check($contact!==null&&!str_contains($contact['contact_cipher'],'15550000001'));
        $other=$makeSession('+15550000001',str_repeat('a',64),'127.0.0.203');problem(409,fn()=> $broker->submit($other['input']));same(1,$remoteCalls);
        $resume=$makeSession('+15550000001',str_repeat('a',64),'127.0.0.204',$sessionData['private']);same('prepared',$broker->submit($resume['input'])['state']);same(1,$remoteCalls);
    };
    $tests['lost worker response retains quota and retries only the same operation before enforcing daily capacity']=function()use($app,$broker,$makeSession,&$remoteCalls,&$remoteState,&$remoteIds):void {
        $second=$makeSession('+15550000002',str_repeat('a',64),'127.0.0.205');$remoteState='timeout';same('retry_wait',$broker->submit($second['input'])['state']);same(2,$remoteCalls);
        same('retry_wait',$broker->submit($second['input'])['state']);same(2,$remoteCalls);
        $over=$makeSession('+15550000003',str_repeat('b',64),'127.0.0.206');problem(429,fn()=> $broker->submit($over['input']));same(2,$remoteCalls);
        $remoteState='prepared';$app->db->query('UPDATE trial_signup_operations SET next_attempt_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE id=?',[$second['operation']]);same('prepared',$broker->status($second['input'])['state']);same(3,$remoteCalls);same(2,count($remoteIds));
    };
    $tests['unpublishing stops new sessions but does not revoke an already-created scoped handoff']=function()use($offers,$broker,$beta,&$brand,&$sessionData,$sessions):void {
        $offers->publish($beta,['expected_revision'=>(int)$offers->managerState($beta,[])['publication']['revision'],'enabled'=>false]);same(false,$offers->publicInfo($brand['id'])['available']);problem(409,fn()=> $sessions->create(['brand_id'=>$brand['id']],'127.0.0.207'));
        same('prepared',$broker->status($sessionData['input'])['state']);same('delivered',$broker->acknowledge($sessionData['input'])['state']);check(!isset($broker->status($sessionData['input'])['activation_code']));
    };
    $tests['default-off public HTTP routes expose no offer and cannot use client reseller or plan claims']=function()use($http,&$brand):void {
        $r=$http->request('GET','/api/public-trials/offer?brand_id='.$brand['id'],null,[],'public-prospect');same(200,$r['status']);same(false,$r['body']['available']);$r=$http->request('POST','/api/public-trials/session',['brand_id'=>$brand['id'],'device_claim'=>str_repeat('a',64)],[],'public-prospect');same(409,$r['status']);
